import React,{useEffect,useState} from 'react';import {createRoot} from 'react-dom/client';
import {PublishedWorkspace,DictionaryWorkspace} from '../../src/features/dictionary/DictionaryAdmin';
import DictionaryBrowser from '../../src/features/dictionary/DictionaryBrowser';
import {LanguageProvider} from '../../src/lib/LanguageContext';import ConfirmDialogHost from '../../src/components/ConfirmDialog';
const post=(path,body)=>fetch(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json());
class Query{constructor(table){this.plan={table,columns:'*',filters:[],orders:[],limit:100};}select(columns){this.plan.columns=columns;return this;}eq(key,value){this.plan.filters.push({key,value,op:'eq'});return this;}in(key,value){this.plan.filters.push({key,value,op:'in'});return this;}contains(key,value){this.plan.filters.push({key,value,op:'contains'});return this;}ilike(key,value){this.plan.filters.push({key,value,op:'ilike'});return this;}order(key,options={}){this.plan.orders.push({key,ascending:options.ascending!==false});return this;}limit(n){this.plan.limit=n;return this;}range(a,b){this.plan.offset=a;this.plan.limit=b-a+1;return this;}maybeSingle(){this.plan.single=true;return post('/query',this.plan);}then(resolve,reject){return post('/query',this.plan).then(resolve,reject);}}
window.dictionaryClient={rpc:(name,args={})=>post('/rpc',{name,args}),from:table=>new Query(table),auth:{getUser:async()=>({data:{user:{id:'fixture-admin'}}}),onAuthStateChange:cb=>{queueMicrotask(()=>cb('SIGNED_IN',{user:{id:'fixture-admin'}}));return {data:{subscription:{unsubscribe(){}}}};}}};
function App(){const[detail,setDetail]=useState(null),[epoch,setEpoch]=useState(0),p=new URLSearchParams(location.search),id=p.get('entry');useEffect(()=>{if(!id)return;window.dictionaryClient.rpc('get_dictionary_entry',{entry_uuid:id}).then(({data})=>setDetail(data));},[id,epoch]);return <LanguageProvider initialLanguage={p.get('lang')??'zh-TW'}><main className="mx-auto max-w-4xl p-3">{p.has('reader')?<DictionaryBrowser path={[]}/>:id?detail&&<PublishedWorkspace key={epoch} detail={detail} entries={[]} senses={[]} refresh={async()=>setEpoch(n=>n+1)}/>:<DictionaryWorkspace/>}<ConfirmDialogHost/></main></LanguageProvider>;}
createRoot(document.getElementById('root')).render(<App/>);
